/**
 * Wikipedia weekly pageviews for the Social Pulse feature (Job A counter).
 *
 * Uses the Wikimedia AQS REST API — free, no key. Wikimedia's 2026 rate
 * limits require a descriptive User-Agent from non-browser clients; ~120
 * requests/week is far inside any limit but the UA is mandatory anyway.
 *
 * Article titles come from data/wikipedia-title-map.json (generated by
 * scripts/map-show-wikipedia-articles.js). Views measure general-public
 * interest, not social chatter — a complementary low-weight signal. Known
 * contamination: shows with film/TV adaptations (Wicked, Mean Girls) carry
 * screen-driven views; the low SIGNAL_WEIGHT + log scaling in the scorer
 * bound the damage.
 */

const USER_AGENT = 'BroadwayScorecard/1.0 (https://broadwayscorecard.com; social-pulse weekly counter)';

/**
 * Fetches total pageviews for an article over the trailing 7 full days
 * (yesterday inclusive, going back — today's partial day is excluded so
 * consecutive Monday runs compare like with like).
 *
 * @param {string} articleTitle Canonical article title, spaces OK
 *   (converted to underscores per AQS requirements).
 * @param {object} [opts]
 * @param {number} [opts.now] Epoch ms "now" override for tests.
 * @param {object} [opts.logger]
 * @returns {Promise<number|null>} Summed views, or null on any failure
 *   (missing article, API error) — null means "signal absent" downstream.
 */
async function fetchWeeklyPageviews(articleTitle, { now = Date.now(), logger = console } = {}) {
  if (!articleTitle || typeof articleTitle !== 'string') return null;

  const day = 24 * 60 * 60 * 1000;
  const fmt = (ms) => {
    const d = new Date(ms);
    return `${d.getUTCFullYear()}${String(d.getUTCMonth() + 1).padStart(2, '0')}${String(d.getUTCDate()).padStart(2, '0')}`;
  };
  const end = fmt(now - day); // yesterday
  const start = fmt(now - 7 * day);

  const article = encodeURIComponent(articleTitle.replace(/ /g, '_'));
  const url = `https://wikimedia.org/api/rest_v1/metrics/pageviews/per-article/en.wikipedia/all-access/user/${article}/daily/${start}00/${end}00`;

  try {
    const res = await fetch(url, { headers: { 'User-Agent': USER_AGENT } });
    if (!res.ok) {
      // 404 = article has no pageview data (new/renamed) — not an error worth noise
      if (res.status !== 404) {
        logger.warn(`[wikipedia] pageviews ${res.status} for "${articleTitle}"`);
      }
      return null;
    }
    const data = await res.json();
    if (!Array.isArray(data.items) || data.items.length === 0) return null;
    return data.items.reduce((sum, item) => sum + (item.views || 0), 0);
  } catch (err) {
    logger.warn(`[wikipedia] pageviews failed for "${articleTitle}": ${err.message}`);
    return null;
  }
}

module.exports = { fetchWeeklyPageviews, USER_AGENT };
